package pagos;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.Map;import org.junit.jupiter.api.Test;import config.ConfiguracionMercadoPago;
class PasarelaPagoFactoryTest {@Test void sinConfiguracionDevuelvePasarelaCerrada(){var p=PasarelaPagoFactory.crear(ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","false")));assertFalse(p.disponible());assertThrows(IllegalStateException.class,()->p.consultarPago("1"));}@Test void preflightValidoCreaPasarelaReal(){var c=ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true","MP_ACCESS_TOKEN","APP_USR-test","MP_WEBHOOK_SECRET","y","MP_PUBLIC_BASE_URL","https://club.example","MP_TEST_USER_ID","123"));PreflightMercadoPago pre=mock(PreflightMercadoPago.class);when(pre.verificar(c)).thenReturn(new PreflightMercadoPago.Resultado(true,"SANDBOX_VERIFICADO"));var p=PasarelaPagoFactory.crear(c,pre);assertTrue(p.disponible());assertInstanceOf(MercadoPagoPasarela.class,p);}@Test void identidadDistintaFallaCerrado(){var c=ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true","MP_ACCESS_TOKEN","APP_USR-test","MP_WEBHOOK_SECRET","y","MP_PUBLIC_BASE_URL","https://club.example","MP_TEST_USER_ID","123"));PreflightMercadoPago pre=mock(PreflightMercadoPago.class);when(pre.verificar(c)).thenReturn(new PreflightMercadoPago.Resultado(false,"IDENTIDAD_NO_COINCIDE"));assertFalse(PasarelaPagoFactory.crear(c,pre).disponible());}}
